#include <openssl/dsa.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>

char* create_dsa_key_securely() {
    DSA *dsa = DSA_new();
    if (!dsa) {
        fprintf(stderr, "Failed to create DSA object\n");
        return NULL;
    }

    // Generate DSA parameters
    if (!DSA_generate_parameters_ex(dsa, 1024, 0, NULL, 0, NULL, NULL)) {
        fprintf(stderr, "DSA parameter generation failed: %s\n", ERR_error_string(ERR_get_error(), NULL));
        DSA_free(dsa);
        return NULL;
    }

    // Generate private key
    if (!DSA_generate_key(dsa)) {
        fprintf(stderr, "DSA key generation failed: %s\n", ERR_error_string(ERR_get_error(), NULL));
        DSA_free(dsa);
        return NULL;
    }

    // Write PEM format key to memory
    BIO *bio = BIO_new(BIO_s_mem());
    if (!PEM_write_bio_DSA_PUBKEY(bio, dsa) || !PEM_write_bio_DSA_PrivateKey(bio, dsa, NULL, 0, NULL)) {
        fprintf(stderr, "Failed to write DSA key to BIO\n");
        BIO_free(bio);
        DSA_free(dsa);
        return NULL;
    }

    // Get the PEM string
    char *key_str;
    long key_len = BIO_get_mem_data(bio, &key_str);
    char *result = (char *)malloc(key_len + 1);
    if (!result) {
        fprintf(stderr, "Memory allocation failed\n");
        BIO_free(bio);
        DSA_free(dsa);
        return NULL;
    }
    memcpy(result, key_str, key_len);
    result[key_len] = '\0';

    BIO_free(bio);
    DSA_free(dsa);

    return result;
}
